import{_ as e,o as t,c as s,a2 as r}from"./chunks/framework.kOe0DhAP.js";const _=JSON.parse('{"title":"消息、上传与国际化","description":"公共服务失败时，业务结果和用户通知应分别判断。","frontmatter":{"title":"消息、上传与国际化","description":"公共服务失败时，业务结果和用户通知应分别判断。"},"headers":[],"relativePath":"15/1502/150002.md","filePath":"15/1502/150002.md"}'),o={name:"15/1502/150002.md"};function i(d,a,l,n,c,h){return t(),s("div",null,[...a[0]||(a[0]=[r('<div class="doc-eyebrow">公共基础服务 / TGEX KNOWLEDGE BASE</div><h1 id="消息、上传与国际化" tabindex="-1">消息、上传与国际化 <a class="header-anchor" href="#消息、上传与国际化" aria-label="Permalink to &quot;消息、上传与国际化&quot;">​</a></h1><div class="doc-lead">公共服务失败时，业务结果和用户通知应分别判断。</div><h2 id="messages" tabindex="-1">消息、短信与邮件 <a class="header-anchor" href="#messages" aria-label="Permalink to &quot;消息、短信与邮件 {#messages}&quot;">​</a></h2><p>业务成功和通知成功是两个结果。订单已完成但短信发送失败，不应回滚交易。通知重试需要防重复、限频与敏感信息处理。</p><h2 id="upload" tabindex="-1">文件上传 <a class="header-anchor" href="#upload" aria-label="Permalink to &quot;文件上传 {#upload}&quot;">​</a></h2><p>区分公开内容与身份认证、申诉等私密材料。上传应验证文件类型、大小、归属与访问权限，不能因为拿到链接就获得永久访问权。</p><h2 id="i18n" tabindex="-1">国际化 <a class="header-anchor" href="#i18n" aria-label="Permalink to &quot;国际化 {#i18n}&quot;">​</a></h2><p>业务错误应有稳定含义，再映射为不同语言文案。翻译变化不应改变错误的处理方式；金额、时间和产品名称需要统一展示约定。</p><h2 id="tasks" tabindex="-1">定时任务 <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;定时任务 {#tasks}&quot;">​</a></h2><p>任务应记录执行范围、游标、结果和重试依据。多实例部署时需要考虑重复触发，尤其是周期结算、奖励发放与资金归集。</p>',11)])])}const u=e(o,[["render",i]]);export{_ as __pageData,u as default};
